INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Aries', '', 'Quan hệ đối tác được đánh dấu bởi đam mê, sự năng động và nhu cầu có một nửa mạnh mẽ, độc lập. Bạn bị thu hút bởi người dám thách thức bạn.', 'Bạn tìm kiếm đối tác mạnh mẽ, quyết đoán. Mối quan hệ của bạn đầy năng lượng nhưng cũng dễ xảy ra xung đột vì cả hai đều muốn dẫn đầu.', 'Đam mê mãnh liệt trong mối quan hệ, sự thẳng thắn và khả năng khơi dậy lửa trong quan hệ đối tác.', 'Xung đột thường xuyên, thiếu kiên nhẫn với đối tác và xu hướng biến mối quan hệ thành cuộc thi quyền lực.', 'Bạn cần người bạn đời vừa mạnh mẽ vừa biết tôn trọng. Mối quan hệ tốt nhất khi cả hai là đối thủ đáng gờm nhưng cùng phe.', 'Học cách thỏa hiệp mà không cảm thấy thua cuộc. Trong mối quan hệ, hợp tác quan trọng hơn chiến thắng.', ARRAY['Nhà 7', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Taurus', '', 'Quan hệ đối tác hướng tới sự ổn định, trung thành và xây dựng bền vững. Bạn tìm kiếm sự an toàn và đáng tin cậy nơi đối tác.', 'Bạn cam kết sâu sắc trong mối quan hệ, tìm kiếm người vững chắc như bạn. Hôn nhân là khoản đầu tư dài hạn mà bạn gây dựng kiên nhẫn.', 'Lòng trung thành phi thường, sự kiên nhẫn với đối tác và khả năng xây dựng mối quan hệ bền vững theo thời gian.', 'Sở hữu đối tác, bướng bỉnh trong tranh cãi và khó thích ứng khi mối quan hệ cần thay đổi.', 'Bạn là người bạn đời trung thành nhất. Bạn thể hiện tình yêu qua sự ổn định, chăm sóc vật chất và sự hiện diện bền bỉ.', 'Linh hoạt trong kỳ vọng về đối tác. Mối quan hệ bền vững cần sự phát triển, không chỉ sự ổn định.', ARRAY['Nhà 7', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Gemini', '', 'Quan hệ đối tác cần giao tiếp, sự kích thích trí tuệ và tính linh hoạt. Bạn tìm kiếm tri kỷ trí tuệ hơn là tình yêu thuần cảm xúc.', 'Bạn cần người bạn đời biết trò chuyện, hài hước và linh hoạt. Mối quan hệ tốt nhất khi cả hai liên tục học hỏi từ nhau.', 'Giao tiếp cởi mở trong mối quan hệ, khả năng thích ứng với thay đổi và giữ mối quan hệ luôn tươi mới, thú vị.', 'Hời hợt trong cam kết, khó tập trung vào một người và dễ mâu thuẫn do thay đổi ý kiến liên tục.', 'Bạn là người bạn đời thú vị và đa dạng. Cuộc trò chuyện là chất keo gắn kết — khi hết chuyện nói, mối quan hệ gặp nguy.', 'Cam kết cảm xúc sâu hơn bên cạnh kết nối trí tuệ. Không chỉ nói mà còn cần cảm nhận.', ARRAY['Nhà 7', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Cancer', '', 'Quan hệ đối tác là nơi tìm kiếm sự an toàn cảm xúc, nuôi dưỡng lẫn nhau và xây dựng tổ ấm chung.', 'Bạn tìm kiếm người bạn đời mang lại cảm giác "về nhà." Hôn nhân là thánh đường cảm xúc — nơi bạn chữa lành và được chữa lành.', 'Sự chăm sóc sâu sắc trong mối quan hệ, trực giác về nhu cầu đối tác và khả năng tạo tổ ấm tình yêu.', 'Phụ thuộc cảm xúc, sợ bị bỏ rơi đến mức bám víu và tâm trạng thất thường ảnh hưởng mối quan hệ.', 'Bạn nuôi dưỡng mối quan hệ như chăm sóc em bé — tận tụy nhưng đôi khi quá bảo bọc. Bạn cần đối tác thấu hiểu chiều sâu cảm xúc.', 'Xây dựng sự an toàn cảm xúc từ bên trong. Người bạn đời là bổ sung, không phải nguồn duy nhất của sự an toàn.', ARRAY['Nhà 7', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Leo', '', 'Quan hệ đối tác cần sự lãng mạn rực rỡ, lòng tự hào chung và mong muốn cùng nhau tỏa sáng trước thế giới.', 'Bạn muốn mối quan hệ đáng tự hào — đôi bạn đẹp đôi, ghen tỵ. Bạn hào phóng trong tình yêu và mong đối tác cũng trân trọng tương xứng.', 'Sự hào phóng trong tình yêu, lòng trung thành sắt đá và khả năng biến mối quan hệ thành câu chuyện tình đẹp.', 'Cần được ngưỡng mộ bởi đối tác, kịch tính hóa vấn đề quan hệ và cái tôi lớn cản trở sự thỏa hiệp.', 'Bạn yêu hết mình và muốn được yêu hết mình. Bạn tìm kiếm người bạn đời xứng đáng đứng cạnh trên "sân khấu" cuộc đời.', 'Tình yêu bền vững không cần khán giả. Học cách yêu trong những khoảnh khắc bình dị, không chỉ những lúc rực rỡ.', ARRAY['Nhà 7', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Virgo', '', 'Quan hệ đối tác được xây dựng trên sự phục vụ lẫn nhau, cải thiện liên tục và tiêu chuẩn cao cho cả hai bên.', 'Bạn kỹ tính khi chọn đối tác — phân tích kỹ lưỡng trước khi cam kết. Mối quan hệ tốt nhất khi cả hai giúp nhau trở nên tốt hơn mỗi ngày.', 'Sự tận tụy thầm lặng, khả năng cải thiện mối quan hệ qua hành động cụ thể và tình yêu thể hiện qua phục vụ.', 'Quá phê phán đối tác, kỳ vọng hoàn hảo không thực tế và khó bày tỏ tình cảm bằng lời.', 'Bạn yêu bằng hành động — chăm sóc, hỗ trợ, giải quyết vấn đề. Bạn cần đối tác hiểu và trân trọng ngôn ngữ tình yêu này.', 'Chấp nhận sự không hoàn hảo của đối tác. Tình yêu không phải dự án cần tối ưu hóa — nó cần sự chấp nhận vô điều kiện.', ARRAY['Nhà 7', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Libra', '', 'Quan hệ đối tác là trung tâm cuộc sống — hài hòa, công bằng và tôn trọng lẫn nhau. Bạn sinh ra để hợp tác.', 'Bạn phát triển mạnh nhất trong mối quan hệ. Bạn tìm kiếm sự cân bằng hoàn hảo — bạn đời vừa đẹp vừa thông minh, vừa mạnh vừa dịu dàng.', 'Kỹ năng quan hệ đối tác xuất sắc, sự công bằng trong xử lý mâu thuẫn và khả năng tạo dựng mối quan hệ hài hòa.', 'Mất bản sắc trong mối quan hệ, sợ cô đơn đến mức chấp nhận mối quan hệ không phù hợp và do dự khi cần kết thúc.', 'Bạn là đối tác lý tưởng — biết lắng nghe, công bằng và duyên dáng. Nguy hiểm duy nhất là đánh mất mình trong đối phương.', 'Học cách hạnh phúc một mình trước khi tìm kiếm hạnh phúc trong mối quan hệ. Bạn hoàn chỉnh một mình, đối tác chỉ bổ sung.', ARRAY['Nhà 7', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Scorpio', '', 'Quan hệ đối tác mang chiều sâu mãnh liệt — chuyển hóa, đam mê và sự gắn kết tâm hồn tuyệt đối hoặc không gì cả.', 'Bạn tìm kiếm mối quan hệ sâu sắc, đầy cường độ. Hôn nhân là sự hợp nhất hoàn toàn — bạn muốn biết mọi bí mật của đối phương.', 'Cam kết sâu sắc tuyệt đối, sự gắn kết tâm hồn mãnh liệt và khả năng chuyển hóa cả hai qua mối quan hệ.', 'Ghen tuông mãnh liệt, tranh giành quyền lực trong mối quan hệ và khó tha thứ khi bị phản bội.', 'Bạn yêu toàn bộ hoặc không yêu. Đối tác phải sẵn sàng cho sự thân mật tuyệt đối — cả thể xác lẫn tâm hồn.', 'Tin tưởng là nền tảng. Học cách buông bỏ kiểm soát và cho phép đối tác có không gian riêng mà không cảm thấy bất an.', ARRAY['Nhà 7', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Sagittarius', '', 'Quan hệ đối tác là cuộc phiêu lưu chung — tự do, mở rộng tầm nhìn và cùng nhau khám phá ý nghĩa cuộc sống.', 'Bạn tìm kiếm đối tác phiêu lưu, cùng du lịch và triết lý. Bạn cần tự do trong mối quan hệ — sự kiểm soát là chất độc.', 'Tầm nhìn rộng mở trong mối quan hệ, sự lạc quan và khả năng mang lại niềm vui, ý nghĩa cho đối tác.', 'Sợ cam kết, quá thẳng thắn gây tổn thương đối tác và xu hướng lý tưởng hóa mối quan hệ.', 'Bạn là đối tác đầy năng lượng và vui vẻ. Bạn cần người bạn đời sẵn sàng khám phá thế giới và không giam giữ bạn.', 'Cam kết không phải sự giam cầm — đó là lựa chọn hàng ngày để cùng phiêu lưu với một người đặc biệt.', ARRAY['Nhà 7', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Capricorn', '', 'Quan hệ đối tác được xây dựng trên sự nghiêm túc, cam kết lâu dài và mục tiêu chung rõ ràng. Hôn nhân là dự án cuộc đời.', 'Bạn chọn đối tác cẩn thận, coi trọng sự ổn định và tham vọng chung. Bạn cam kết một khi đã quyết định — và kỳ vọng đối phương cũng vậy.', 'Cam kết sắt đá, khả năng xây dựng mối quan hệ bền vững và tầm nhìn dài hạn trong quan hệ đối tác.', 'Quá nghiêm túc, thiếu sự lãng mạn tự phát và xu hướng đánh giá mối quan hệ qua thước đo thực dụng.', 'Bạn là đối tác đáng tin cậy nhất. Bạn thể hiện tình yêu qua hành động, trách nhiệm và sự bảo đảm tương lai.', 'Cho phép sự vui tươi và tự phát trong mối quan hệ. Tình yêu cần cả kế hoạch lẫn những bất ngờ ngọt ngào.', ARRAY['Nhà 7', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Aquarius', '', 'Quan hệ đối tác cần sự tự do, bình đẳng và kết nối trí tuệ. Bạn tìm kiếm bạn tốt nhất hơn là tình yêu truyền thống.', 'Bạn cần không gian cá nhân trong mối quan hệ. Đối tác lý tưởng là người bạn thân trí tuệ, chia sẻ lý tưởng và tôn trọng sự độc lập.', 'Sự bình đẳng trong mối quan hệ, tầm nhìn tiến bộ về quan hệ đối tác và khả năng duy trì tình bạn trong tình yêu.', 'Xa cách cảm xúc, quá độc lập đến mức cô lập đối tác và khó chấp nhận các khuôn mẫu quan hệ truyền thống.', 'Bạn là đối tác bình đẳng và thú vị. Bạn cần người hiểu rằng tự do cá nhân và tình yêu có thể cùng tồn tại.', 'Sự kết nối cảm xúc sâu sắc cũng quan trọng như sự kết nối trí tuệ. Đôi khi cần bước ra khỏi vùng thoải mái trí tuệ để chạm vào trái tim.', ARRAY['Nhà 7', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Pisces', '', 'Quan hệ đối tác là trải nghiệm tâm linh — sự hòa nhập cảm xúc, lòng hy sinh và mong muốn yêu thương vô điều kiện.', 'Bạn tìm kiếm tình yêu siêu việt, gần như tâm linh. Bạn dễ lý tưởng hóa đối tác và hy sinh bản thân vì mối quan hệ.', 'Lòng trắc ẩn vô bờ, trực giác về nhu cầu đối tác và khả năng yêu thương vô điều kiện, tha thứ sâu sắc.', 'Mất bản thân trong đối phương, ảo tưởng về mối quan hệ, dễ bị lợi dụng và khó thiết lập ranh giới.', 'Bạn yêu với trái tim mở hoàn toàn. Bạn cần đối tác trung thực vì bạn dễ bị tổn thương — sự tin tưởng là tất cả.', 'Yêu thương mà không đánh mất bản thân. Thiết lập ranh giới lành mạnh để tình yêu nuôi dưỡng cả hai, không chỉ một người.', ARRAY['Nhà 7', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Aries', '', 'Chuyển hóa sâu sắc đến qua hành động quyết đoán, đối mặt trực diện với khủng hoảng và sự can đảm khám phá bóng tối.', 'Bạn đối mặt với khủng hoảng bằng sức mạnh chiến binh. Bạn không ngại chủ đề cấm kỵ — sự sống, cái chết, quyền lực — và biến mọi thử thách thành cơ hội.', 'Sức bật phi thường sau khủng hoảng, lòng can đảm khám phá chiều sâu tâm lý và khả năng hành động nhanh trong tình huống nguy hiểm.', 'Liều lĩnh với tài sản chung, xung đột về quyền kiểm soát tài chính và bốc đồng trong các quyết định quan trọng.', 'Sự thân mật với bạn mãnh liệt và trực tiện. Bạn cần đối tác không sợ chiều sâu cảm xúc và sẵn sàng cho sự chuyển hóa liên tục.', 'Kiên nhẫn trong quá trình chuyển hóa. Không phải mọi khủng hoảng đều cần phản ứng tức thì — đôi khi sự chờ đợi là khôn ngoan nhất.', ARRAY['Nhà 8', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Taurus', '', 'Chuyển hóa diễn ra chậm rãi, sâu sắc qua giá trị vật chất, giác quan và sự buông bỏ những gì đã quen thuộc.', 'Bạn gắn bó mạnh mẽ với tài sản chung và ngại thay đổi triệt để. Nhưng khi chuyển hóa đến, nó tái tạo bạn hoàn toàn từ nền tảng vật chất.', 'Quản lý tài sản chung xuất sắc, kiên nhẫn qua quá trình chuyển hóa dài và khả năng xây dựng lại từ đống tro tàn.', 'Bám víu quá mức vào tài sản, sợ mất mát đến mức tê liệt và kháng cự sự thay đổi cần thiết.', 'Sự thân mật với bạn gắn liền với giác quan và sự an toàn. Bạn cần đối tác minh bạch về tài chính và cam kết lâu dài.', 'Buông bỏ là dạng chuyển hóa mạnh mẽ nhất. Sự giàu có thực sự nằm ở khả năng buông bỏ, không phải tích lũy.', ARRAY['Nhà 8', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Gemini', '', 'Chuyển hóa đến qua tri thức, giao tiếp sâu sắc và sự hiểu biết về những bí ẩn ẩn giấu đằng sau bề mặt.', 'Bạn bị thu hút bởi bí ẩn, trinh thám tâm lý và nghiên cứu sâu. Bạn chuyển hóa qua đối thoại, viết lách và khám phá tri thức cấm.', 'Trí tuệ thấu thị, khả năng giao tiếp về chủ đề nhạy cảm và tài năng nghiên cứu chuyên sâu.', 'Lo âu về cái chết và sự thay đổi, suy nghĩ quá nhiều về những điều bí ẩn và khó ngồi yên với sự không chắc chắn.', 'Bạn cần đối tác có thể thảo luận sâu về mọi chủ đề. Sự thân mật bắt đầu từ cuộc trò chuyện thẳng thắn về mọi điều.', 'Đôi khi cần cảm nhận thay vì phân tích. Không phải mọi bí ẩn đều cần lời giải — một số cần được sống qua.', ARRAY['Nhà 8', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Cancer', '', 'Chuyển hóa gắn liền với cảm xúc sâu thẳm, ký ức gia tộc và quá trình chữa lành vết thương tiềm thức.', 'Bạn trải nghiệm chuyển hóa qua cảm xúc mãnh liệt — mất mát, sinh nở, chia ly. Bạn mang trong mình ký ức và nghiệp gia tộc sâu sắc.', 'Trực giác tâm linh mạnh mẽ, khả năng chữa lành cảm xúc cho người khác và sức bật phi thường qua đau khổ.', 'Bám víu nỗi đau quá khứ, sợ mất mát cảm xúc đến mức tê liệt và dễ bị chìm đắm trong cảm xúc tiêu cực.', 'Sự thân mật với bạn vô cùng sâu sắc và đầy cảm xúc. Bạn cần đối tác an toàn — người không bao giờ sử dụng sự dễ bị tổn thương chống lại bạn.', 'Buông bỏ nỗi đau quá khứ để cho phép sự tái sinh. Mỗi mất mát mang đến một khởi đầu mới nếu bạn cho phép.', ARRAY['Nhà 8', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Leo', '', 'Chuyển hóa gắn liền với quyền lực cá nhân, sự tái tạo bản ngã và khám phá sức mạnh sáng tạo sâu thẳm.', 'Bạn trải nghiệm chuyển hóa qua các cuộc khủng hoảng bản ngã — khi mất tất cả, bạn phát hiện sức mạnh nội tại phi thường.', 'Sức mạnh nội tại vĩ đại, khả năng lãnh đạo trong khủng hoảng và sự kiêu hãnh giúp đứng dậy sau mọi thất bại.', 'Cái tôi lớn cản trở sự chuyển hóa cần thiết, khó chấp nhận sự dễ bị tổn thương và tranh giành quyền lực trong tài chính chung.', 'Sự thân mật với bạn đầy đam mê và sáng tạo. Bạn cần đối tác ngưỡng mộ sức mạnh nội tại nhưng không phải đối thủ quyền lực.', 'Sự dễ bị tổn thương là dạng sức mạnh cao nhất. Cho phép bản thân tan vỡ để tái sinh mạnh mẽ hơn.', ARRAY['Nhà 8', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Virgo', '', 'Chuyển hóa diễn ra qua phân tích chi tiết, thanh lọc và quá trình cải thiện bản thân từng bước nhỏ nhưng sâu sắc.', 'Bạn chuyển hóa bằng cách phân tích mọi khía cạnh — sức khỏe, thói quen, tâm lý. Bạn có thể bị thu hút bởi y học, nghiên cứu hoặc liệu pháp.', 'Khả năng phân tích vấn đề sâu sắc, sự tỉ mỉ trong quản lý tài sản chung và tài năng chẩn đoán vấn đề ẩn giấu.', 'Lo lắng ám ảnh về sức khỏe và cái chết, phân tích quá mức thay vì cảm nhận và khó buông bỏ kiểm soát.', 'Sự thân mật cần cảm giác sạch sẽ, an toàn và có trật tự. Bạn phân tích mối quan hệ sâu thay vì đơn giản cảm nhận.', 'Không phải mọi thứ cần phân tích. Đôi khi chuyển hóa đến qua việc buông bỏ nhu cầu hiểu và đơn giản chấp nhận.', ARRAY['Nhà 8', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Libra', '', 'Chuyển hóa đến qua các mối quan hệ — sự thân mật sâu sắc là con đường tái sinh và phát triển.', 'Bạn chuyển hóa mạnh mẽ nhất qua quan hệ đối tác. Mỗi mối quan hệ sâu sắc thay đổi bạn vĩnh viễn. Tài sản chung được quản lý công bằng.', 'Khả năng đàm phán tài sản chung xuất sắc, sự công bằng trong chia sẻ nguồn lực và tài năng hòa giải trong khủng hoảng.', 'Phụ thuộc vào đối tác cho sự chuyển hóa, tránh đối mặt với bóng tối nội tâm và sợ mất cân bằng trong mối quan hệ sâu.', 'Sự thân mật là quá trình chia sẻ bình đẳng. Bạn cần đối tác sẵn sàng cùng nhau khám phá chiều sâu và chia sẻ mọi thứ công bằng.', 'Chuyển hóa cũng có thể là hành trình cá nhân. Đừng chờ đợi mối quan hệ mới để bắt đầu tái sinh bản thân.', ARRAY['Nhà 8', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Scorpio', '', 'Chuyển hóa ở đây mạnh mẽ nhất — sâu thẳm, triệt để và không thể đảo ngược. Bạn sinh ra để chết đi và tái sinh nhiều lần trong đời.', 'Bạn trải nghiệm những cuộc chuyển hóa tàn khốc nhưng huy hoàng. Bạn hiểu bản chất của quyền lực, sự sống, cái chết và sự tái sinh ở cấp độ bản năng.', 'Sức mạnh tâm lý phi thường, trực giác thấu thị về bản chất con người và khả năng sống sót qua mọi khủng hoảng.', 'Ám ảnh kiểm soát, sợ bị phản bội dẫn đến hoang tưởng và xu hướng tự hủy hoại trước khi bị hủy hoại.', 'Sự thân mật là trải nghiệm chuyển hóa hoàn toàn. Bạn đòi hỏi sự trung thực tuyệt đối và trao lại sự gắn kết tâm hồn sâu nhất.', 'Sử dụng sức mạnh chuyển hóa để chữa lành thay vì phá hủy. Phượng hoàng chỉ tái sinh khi chấp nhận ngọn lửa.', ARRAY['Nhà 8', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Sagittarius', '', 'Chuyển hóa đến qua tri thức triết học, tín ngưỡng và sự mở rộng hiểu biết về những bí ẩn vĩ đại của cuộc sống.', 'Bạn tìm kiếm ý nghĩa trong mọi cuộc khủng hoảng. Bạn có thể quan tâm đến triết học về cái chết, tái sinh hoặc các hệ thống tâm linh.', 'Tầm nhìn triết học về sự chuyển hóa, sự lạc quan ngay cả trong bóng tối và khả năng tìm ý nghĩa trong mất mát.', 'Tránh đối mặt trực diện với nỗi đau bằng cách trí tuệ hóa nó, quá lạc quan về rủi ro tài chính chung và bỏ qua chi tiết quan trọng.', 'Sự thân mật gắn liền với chia sẻ niềm tin và triết lý sống. Bạn cần đối tác cùng khám phá ý nghĩa sâu sắc của cuộc sống.', 'Đôi khi cần dừng tìm ý nghĩa và đơn giản cảm nhận nỗi đau. Sự chuyển hóa sâu nhất đến khi ngừng chạy trốn.', ARRAY['Nhà 8', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Capricorn', '', 'Chuyển hóa diễn ra có cấu trúc, kỷ luật và hướng tới xây dựng lại di sản bền vững sau mỗi cuộc khủng hoảng.', 'Bạn đối mặt với khủng hoảng bằng sự thực dụng lạnh lùng. Bạn quản lý tài sản chung với kỷ luật sắt và xây dựng lại từ từ nhưng vững chắc.', 'Sự kiên cường trong khủng hoảng, quản lý tài sản chung xuất sắc và khả năng chuyển hóa vết thương thành bài học.', 'Kìm nén cảm xúc trong khủng hoảng, quá kiểm soát tài sản chung và sợ mất kiểm soát đến mức bỏ lỡ cơ hội chuyển hóa.', 'Sự thân mật cần thời gian và sự tin tưởng. Bạn mở lòng chậm nhưng khi đã mở, sự gắn kết vô cùng bền chắc.', 'Cho phép cảm xúc chảy tự do trong quá trình chuyển hóa. Kiểm soát không phải lúc nào cũng là câu trả lời.', ARRAY['Nhà 8', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Aquarius', '', 'Chuyển hóa đến qua sự giác ngộ trí tuệ, phá vỡ khuôn mẫu cũ và những thay đổi đột ngột, bất ngờ.', 'Bạn trải nghiệm chuyển hóa đột ngột, không báo trước. Bạn có thể quan tâm đến công nghệ, khoa học hoặc tâm lý học xã hội liên quan đến sự sống-chết.', 'Tư duy đột phá về sự chuyển hóa, khả năng chấp nhận thay đổi nhanh chóng và sự khách quan trong khủng hoảng.', 'Xa cách cảm xúc trong khủng hoảng, quá lý trí khi cần cảm nhận và thay đổi đột ngột gây bất ổn cho quan hệ.', 'Sự thân mật cần cả sự kết nối trí tuệ lẫn cảm xúc. Bạn có thể gặp khó khăn khi đối phương cần sự hỗ trợ cảm xúc thuần túy.', 'Chuyển hóa không chỉ là quá trình trí tuệ. Cho phép bản thân cảm nhận sâu sắc và đừng chạy trốn vào lý trí.', ARRAY['Nhà 8', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Pisces', '', 'Chuyển hóa là trải nghiệm tâm linh sâu thẳm — sự hòa tan ranh giới, kết nối với vô thức tập thể và sự tái sinh qua lòng trắc ẩn.', 'Bạn trải nghiệm chuyển hóa qua giấc mơ, thiền định, nghệ thuật hoặc những trải nghiệm tâm linh sâu sắc. Ranh giới giữa bạn và thế giới rất mỏng manh.', 'Trực giác tâm linh phi thường, khả năng chữa lành sâu sắc và sự kết nối với những chiều không gian ý thức cao hơn.', 'Dễ bị ảnh hưởng bởi năng lượng tiêu cực, ranh giới quá yếu trong tài chính chung và xu hướng trốn tránh thực tại qua nghiện.', 'Sự thân mật là trải nghiệm tâm linh siêu việt. Bạn hòa nhập hoàn toàn với đối phương nhưng cần cẩn thận không đánh mất bản thân.', 'Bám trụ vào thực tế trong khi khám phá chiều sâu tâm linh. Sự chuyển hóa thực sự kết hợp cả thế giới vật chất lẫn tâm linh.', ARRAY['Nhà 8', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Aries', '', 'Triết lý sống, giáo dục và du lịch được thúc đẩy bởi tinh thần tiên phong, sự can đảm khám phá và mong muốn tự mình tìm ra chân lý.', 'Bạn khám phá thế giới bằng hành động — du lịch tự túc, tự học, tự tìm đường. Bạn không chấp nhận triết lý ai đó áp đặt mà tự xây dựng niềm tin.', 'Tinh thần phiêu lưu trí tuệ, lòng can đảm thách thức giáo điều và khả năng tìm đường mới trong tư tưởng và du lịch.', 'Giáo điều theo kiểu riêng, bỏ ngang giáo dục khi chán và thiếu kiên nhẫn với hệ thống giáo dục truyền thống.', 'Bạn cần đối tác chia sẻ tầm nhìn và sẵn sàng phiêu lưu. Sự khác biệt văn hóa và tư tưởng làm bạn hứng thú.', 'Kiên nhẫn trong hành trình tri thức. Không phải mọi chân lý đều đến ngay — một số cần thời gian chiêm nghiệm.', ARRAY['Nhà 9', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Taurus', '', 'Triết lý sống dựa trên giá trị thực tế, trải nghiệm giác quan và sự tích lũy tri thức chậm rãi, vững chắc.', 'Bạn học qua trải nghiệm thực tế hơn là lý thuyết. Du lịch hướng tới ẩm thực, thiên nhiên và văn hóa vật chất. Niềm tin phát triển chậm nhưng kiên cố.', 'Nền tảng triết học vững chắc, học tập kiên nhẫn bền bỉ và khả năng áp dụng tri thức vào thực tế cuộc sống.', 'Cứng nhắc trong niềm tin, kháng cự ý tưởng mới và giới hạn tầm nhìn vào những gì có thể sờ nắm.', 'Bạn trân trọng đối tác chia sẻ giá trị cốt lõi. Sự khác biệt văn hóa hấp dẫn nhưng nền tảng giá trị phải tương đồng.', 'Mở rộng tầm nhìn vượt ra ngoài thế giới vật chất. Tri thức trừu tượng và tâm linh cũng có giá trị to lớn.', ARRAY['Nhà 9', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Gemini', '', 'Triết lý sống đa chiều, luôn thay đổi và được nuôi dưỡng bởi sự tò mò trí tuệ vô tận. Bạn thu thập ý tưởng từ mọi nguồn.', 'Bạn đọc rộng, du lịch nhiều và thu thập triết lý từ khắp nơi. Bạn có thể nói nhiều ngôn ngữ hoặc theo đuổi nhiều lĩnh vực học thuật.', 'Tầm nhìn đa văn hóa, khả năng kết nối các hệ tư tưởng khác nhau và tài năng giao tiếp xuyên biên giới.', 'Thiếu chiều sâu triết học, thay đổi niềm tin quá thường xuyên và khó cam kết với một con đường tri thức.', 'Bạn bị thu hút bởi đối tác từ nền văn hóa khác. Cuộc trò chuyện về triết lý, du lịch và ý tưởng lớn là nền tảng mối quan hệ.', 'Phát triển chiều sâu bên cạnh chiều rộng. Đào sâu một hệ tư tưởng thay vì lướt qua tất cả.', ARRAY['Nhà 9', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Cancer', '', 'Triết lý sống gắn liền với truyền thống gia đình, trực giác và sự khám phá thế giới qua lăng kính cảm xúc.', 'Niềm tin của bạn bắt nguồn từ gia đình và quê hương. Du lịch mang tính hoài niệm — tìm về nguồn cội. Bạn học bằng cảm nhận, không chỉ bằng lý trí.', 'Trực giác triết học sâu sắc, kết nối cảm xúc với tri thức và khả năng truyền đạt giá trị gia đình một cách ý nghĩa.', 'Bám víu truyền thống mù quáng, sợ khám phá bên ngoài vùng quen thuộc và để cảm xúc chi phối niềm tin.', 'Bạn muốn chia sẻ hành trình tri thức và du lịch với gia đình. Đối tác cần hiểu tầm quan trọng của nguồn cội trong cuộc sống bạn.', 'Mở rộng vùng an toàn trí tuệ. Tri thức mới không phản bội truyền thống — nó làm phong phú thêm.', ARRAY['Nhà 9', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Leo', '', 'Triết lý sống rực rỡ, đầy tự tin và mong muốn chia sẻ ánh sáng tri thức với thế giới. Bạn sinh ra để truyền cảm hứng.', 'Bạn thể hiện niềm tin đầy đam mê và tự tin. Du lịch sang trọng, giáo dục mang tính biểu diễn — bạn muốn được công nhận như người truyền tải tri thức.', 'Khả năng truyền cảm hứng qua tri thức, sự tự tin trong chia sẻ niềm tin và tài năng giảng dạy cuốn hút.', 'Kiêu ngạo trí tuệ, áp đặt niềm tin lên người khác và biến triết lý thành sân khấu cá nhân.', 'Bạn bị thu hút bởi đối tác ngưỡng mộ trí tuệ và tầm nhìn của bạn. Chia sẻ tri thức là cách bạn kết nối sâu sắc.', 'Lắng nghe triết lý của người khác. Ánh sáng tri thức sáng hơn khi được chia sẻ bình đẳng.', ARRAY['Nhà 9', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Virgo', '', 'Triết lý sống dựa trên phân tích, thực hành và sự theo đuổi tri thức có thể áp dụng vào cuộc sống thực tế.', 'Bạn học tỉ mỉ, nghiên cứu kỹ và áp dụng tri thức vào thực tế. Du lịch có mục đích — học ngôn ngữ, tình nguyện, nghiên cứu văn hóa.', 'Tư duy phân tích sâu sắc trong triết học, học tập có hệ thống và khả năng áp dụng lý thuyết vào thực tế.', 'Quá phê phán các hệ tư tưởng, thiếu tin vào những gì không thể chứng minh và lo lắng quá mức khi du lịch.', 'Bạn trân trọng đối tác chia sẻ giá trị học tập và cải thiện liên tục. Cùng nhau phát triển là nền tảng mối quan hệ.', 'Cho phép sự kỳ diệu và bí ẩn tồn tại. Không phải mọi chân lý đều có thể đo lường hoặc phân tích.', ARRAY['Nhà 9', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Libra', '', 'Triết lý sống hướng tới sự công bằng, cân bằng và vẻ đẹp trong mọi nền văn hóa và hệ tư tưởng.', 'Bạn tìm kiếm sự hài hòa giữa các triết lý khác nhau. Du lịch hướng tới nghệ thuật, kiến trúc và văn hóa. Giáo dục về công bằng xã hội thu hút bạn.', 'Tầm nhìn công bằng về các nền văn hóa, khả năng hòa giải giữa các hệ tư tưởng đối lập và cảm nhận thẩm mỹ đa văn hóa.', 'Do dự trong niềm tin, thỏa hiệp triết lý để tránh xung đột và thiếu lập trường vững chắc về các vấn đề quan trọng.', 'Bạn cần đối tác chia sẻ hành trình khám phá văn hóa. Cùng nhau du lịch và mở rộng tầm nhìn là nền tảng tình yêu.', 'Đôi khi cần chọn một lập trường và bảo vệ nó. Sự công bằng không có nghĩa là mọi ý kiến đều đúng bằng nhau.', ARRAY['Nhà 9', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Scorpio', '', 'Triết lý sống khám phá bí ẩn sâu thẳm — tâm linh huyền bí, tâm lý học chiều sâu và chân lý ẩn giấu.', 'Bạn bị thu hút bởi tri thức bí mật — chiêm tinh, tâm lý học, huyền học. Du lịch đến những nơi bí ẩn, cổ đại. Bạn tìm chân lý ẩn giấu sau bề mặt.', 'Chiều sâu triết học phi thường, khả năng khám phá chân lý bí ẩn và trực giác mạnh mẽ về bản chất cuộc sống.', 'Ám ảnh với bí ẩn, sợ tin vào những điều sai và xu hướng biến tri thức thành công cụ quyền lực.', 'Bạn tìm kiếm đối tác cùng khám phá chiều sâu cuộc sống. Chia sẻ bí mật và niềm tin sâu sắc là cách bạn kết nối.', 'Tri thức sâu sắc nên được chia sẻ, không nên giữ như vũ khí. Sử dụng sự hiểu biết để chữa lành thay vì kiểm soát.', ARRAY['Nhà 9', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Sagittarius', '', 'Triết lý sống ở đây mạnh mẽ nhất — tầm nhìn rộng mở, lạc quan bất diệt và khát vọng tri thức vô tận. Đây là vị trí tự nhiên.', 'Bạn sinh ra để du lịch, học hỏi và truyền bá tri thức. Bạn có thể là giáo viên, nhà triết học hoặc người du mục trí tuệ.', 'Tầm nhìn triết học vĩ đại, tinh thần phiêu lưu bất tận và khả năng truyền cảm hứng cho người khác qua tri thức.', 'Giáo điều, bỏ qua chi tiết vì quá tập trung vào bức tranh lớn và khó ngồi yên trong một hệ thống tư tưởng.', 'Bạn cần đối tác vừa là bạn đồng hành phiêu lưu vừa là bạn tri thức. Chia sẻ khát vọng tự do là nền tảng tình yêu.', 'Chiều sâu cũng quan trọng như chiều rộng. Đôi khi ở yên một chỗ và đào sâu mang lại tri thức quý giá hơn nhiều chuyến đi.', ARRAY['Nhà 9', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Capricorn', '', 'Triết lý sống dựa trên thực dụng, kỷ luật và mong muốn xây dựng hệ thống tri thức có tính ứng dụng lâu dài.', 'Bạn theo đuổi giáo dục mang tính chiến lược — học để thành công, không chỉ để biết. Du lịch có mục đích nghề nghiệp hoặc học thuật.', 'Kỷ luật trong học tập, tầm nhìn chiến lược về giáo dục và khả năng biến tri thức thành thành tựu cụ thể.', 'Hẹp hòi triết học, chỉ coi trọng tri thức "hữu ích" và bỏ qua giá trị của tri thức thuần túy.', 'Bạn tìm kiếm đối tác chia sẻ tham vọng học thuật và nghề nghiệp. Cùng nhau xây dựng tri thức là nền tảng.', 'Mở rộng định nghĩa về "tri thức hữu ích." Triết học, nghệ thuật và tâm linh cũng làm phong phú cuộc sống.', ARRAY['Nhà 9', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Aquarius', '', 'Triết lý sống tiến bộ, nhân văn và hướng tới tương lai. Bạn bị thu hút bởi tri thức cách mạng và hệ tư tưởng phi truyền thống.', 'Bạn quan tâm đến triết học xã hội, công nghệ tương lai và các phong trào tiến bộ toàn cầu. Du lịch mang tính trải nghiệm cộng đồng.', 'Tầm nhìn nhân văn rộng mở, tư duy tiến bộ vượt thời đại và khả năng kết nối tri thức với cải cách xã hội.', 'Cố chấp với quan điểm cách mạng riêng, xa cách cảm xúc trong niềm tin và nổi loạn với mọi hệ thống giáo dục truyền thống.', 'Bạn cần đối tác chia sẻ lý tưởng nhân văn. Cùng nhau làm cho thế giới tốt đẹp hơn là nền tảng tình yêu.', 'Truyền thống cũng có giá trị. Đôi khi tri thức cổ xưa chứa đựng chân lý mà tư duy hiện đại chưa chạm tới.', ARRAY['Nhà 9', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Pisces', '', 'Triết lý sống mang tính tâm linh, trực giác và hướng tới sự hòa tan mọi ranh giới giữa các hệ tư tưởng.', 'Bạn tìm kiếm chân lý qua thiền định, nghệ thuật và trải nghiệm tâm linh. Du lịch đến những nơi linh thiêng. Niềm tin vượt qua mọi giáo lý cụ thể.', 'Trực giác tâm linh sâu sắc, khả năng kết nối các triết lý khác nhau thành một thể thống nhất và tầm nhìn phổ quát.', 'Dễ bị cuốn vào ảo tưởng tâm linh, thiếu nền tảng logic và khó phân biệt giữa trực giác thực sự và mong muốn cá nhân.', 'Bạn tìm kiếm đối tác chia sẻ hành trình tâm linh. Cùng nhau thiền, du lịch tâm linh và khám phá ý nghĩa cuộc sống.', 'Bám trụ vào thực tế. Tâm linh cần cân bằng với logic để tránh lạc lối trong thế giới ảo tưởng.', ARRAY['Nhà 9', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
